    if (string.IsNullOrWhiteSpace(input.Name))
    {
        _logger.LogWarning("Validation failed: Name is required for {Type}", nameof(Consumer4));
        return false;
    }

    /* Multi-line validation logic:
     * 1. Check field lengths
